package com.google.javascript.jscomp;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import org.junit.Test;

public class com.google.javascript.jscomp.NodeUtilAI141Test {

  @Test
  public void testGetBooleanValue() {
    assertTrue(NodeUtil.getBooleanValue(Node.newString("hello")));
    assertFalse(NodeUtil.getBooleanValue(Node.newString("")));
    assertTrue(NodeUtil.getBooleanValue(Node.newNumber(5.0)));
    assertFalse(NodeUtil.getBooleanValue(Node.newNumber(0.0)));
  }

  @Test
  public void testGetStringValue() {
    assertEquals("hello", NodeUtil.getStringValue(Node.newString("hello")));
    assertEquals("1", NodeUtil.getStringValue(Node.newNumber(1.0)));
    assertEquals("true", NodeUtil.getStringValue(Node.newCheckableNode(Token.TRUE, -1)));
    assertEquals("undefined", NodeUtil.getStringValue(Node.newCheckableNode(Token.VOID, -1)));
  }

  @Test
  public void testHasFinally() {
    Node tryNode = new Node(Token.TRY);
    tryNode.addChildToBack(new Node(Token.BLOCK));
    tryNode.addChildToBack(new Node(Token.BLOCK));
    assertFalse(NodeUtil.hasFinally(tryNode));
    tryNode.addChildToBack(new Node(Token.BLOCK));
    assertTrue(NodeUtil.hasFinally(tryNode));
  }
}
